(function(){var el=document.getElementById("lv-flash");if(!el)return;var DUR=8*60+27,K="lv_flash_end";var end=parseInt(sessionStorage.getItem(K)||"0",10);var now=Math.floor(Date.now()/1000);if(!end||end<=now||end-now>DUR){end=now+DUR;try{sessionStorage.setItem(K,String(end))}catch(e){}}function p(n){return n<10?"0"+n:""+n}function tick(){var s=end-Math.floor(Date.now()/1000);if(s<=0){s=DUR;end=Math.floor(Date.now()/1000)+DUR;try{sessionStorage.setItem(K,String(end))}catch(e){}}el.textContent=p(Math.floor(s/3600))+":"+p(Math.floor(s%3600/60))+":"+p(s%60)}tick();setInterval(tick,1000)})();